import{_ as t,o as i,c as a,a3 as o}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Setting up time tracking","description":"Clock in, break and clock out in the app – the times live in a Grid your staff needs no access to.","frontmatter":{"title":"Setting up time tracking","description":"Clock in, break and clock out in the app – the times live in a Grid your staff needs no access to."},"headers":[],"relativePath":"en/apptiveteams/zeiterfassung.md","filePath":"en/apptiveteams/zeiterfassung.md","lastUpdated":1788793624000}'),r={name:"en/apptiveteams/zeiterfassung.md"};function n(d,e,s,h,l,c){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="setting-up-time-tracking" tabindex="-1">Setting up time tracking <a class="header-anchor" href="#setting-up-time-tracking" aria-label="Permalink to &quot;Setting up time tracking&quot;">​</a></h1><p>A tab of type <code>TimeTracking</code> adds time tracking to the app: <strong>Clock in</strong>, <strong>Break</strong> and <strong>Clock out</strong> at the push of a button, manual entries through a form, a list for today and a week overview. Every recorded time is a row in a Grid of your ApptiveGrid account.</p><p>Your staff needs <strong>no access to the Space</strong> holding the times. The app works through shared links only: a view for reading, a form for creating and one edit link per row for changing. Everyone sees only their own times, and you keep the evaluation in the Grid.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Building block</th><th>Where</th><th>Purpose</th></tr></thead><tbody><tr><td>Grid with the time entries</td><td>time-tracking Space</td><td>Stores the times</td></tr><tr><td>Form on the Grid</td><td>time-tracking Space</td><td>Creates entries, also used for changes</td></tr><tr><td>Filtered, shared view</td><td>time-tracking Space</td><td>Delivers a person&#39;s own entries to the app</td></tr><tr><td>Flow &quot;create edit link&quot;</td><td>time-tracking Space</td><td>Makes break and clock out possible</td></tr><tr><td>Tabs row of type <code>TimeTracking</code></td><td>team Space</td><td>Shows the tab in the app</td></tr></tbody></table><p>The time-tracking Space can be a Space of its own that only you can see. That is the recommended setup.</p><h2 id="_1-the-grid" tabindex="-1">1. The Grid <a class="header-anchor" href="#_1-the-grid" aria-label="Permalink to &quot;1. The Grid&quot;">​</a></h2><p>Create a Grid with these fields. Names are up to you, the <strong>Keys</strong> must match exactly. → <a href="/en/apptiveteams/team-space#keys-how-the-app-finds-its-grids">Assigning keys</a></p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>start</code></td><td>Date and time</td><td>yes</td><td>Start of the working time</td></tr><tr><td><code>end</code></td><td>Date and time</td><td>yes</td><td>End of the working time; empty while it is running</td></tr><tr><td><code>breakMinutes</code></td><td>Number</td><td>yes</td><td>Sum of the breaks in minutes</td></tr><tr><td><code>breakStart</code></td><td>Date and time</td><td>yes</td><td>Start of a running break; otherwise empty</td></tr><tr><td><code>editLink</code></td><td>Weblink</td><td>yes</td><td>Edit link of the row, written by the flow</td></tr><tr><td><code>note</code></td><td>Text</td><td>no</td><td>Note, for example &quot;client meeting&quot;</td></tr><tr><td><code>createdBy</code></td><td>Created by</td><td>yes</td><td>Set automatically; the view filters on it</td></tr></tbody></table><p>Further fields such as project or attachments may live in the Grid; the app leaves them untouched.</p><div class="tip custom-block"><p class="custom-block-title">Net hours in the Grid</p><p>A formula column such as <code>(end - start) - breakMinutes</code> gives you the net working time right in the Grid – for evaluations and exports, without touching the app.</p></div><h2 id="_2-the-form" tabindex="-1">2. The form <a class="header-anchor" href="#_2-the-form" aria-label="Permalink to &quot;2. The form&quot;">​</a></h2><p>Create a form on the Grid with the fields <code>start</code>, <code>end</code>, <code>breakMinutes</code>, <code>breakStart</code> and optionally <code>note</code>. Share it restricted to <strong>Any registered user</strong>: that way each entry records the signed-in person as &quot;Created by&quot;.</p><p>The flow in the next step uses the same form for the edit links. → <a href="/en/formulare/formular-teilen">Sharing a form</a></p><h2 id="_3-the-view" tabindex="-1">3. The view <a class="header-anchor" href="#_3-the-view" aria-label="Permalink to &quot;3. The view&quot;">​</a></h2><p>Create a view on the Grid, filter on <strong>Created by is the signed-in user</strong> and show all fields from step 1. Share the view via link, again for signed-in users only. → <a href="/en/ansichten/ansicht-teilen">Sharing a view</a></p><p>The filter is evaluated on the server. Through the same link, every person receives only their own rows.</p><h2 id="_4-the-flow" tabindex="-1">4. The flow <a class="header-anchor" href="#_4-the-flow" aria-label="Permalink to &quot;4. The flow&quot;">​</a></h2><p>Without an edit link the app cannot change a row; break and clock out stay locked. A flow creates the link automatically:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: entry created                  (Grid from step 1)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Pre-filled form link                    (form from step 2)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Update entry                            → field editLink = created link</span></span></code></pre></div><p>Activate the flow. After clocking in, the app shows &quot;Syncing with ApptiveGrid …&quot; until the link is in the row, usually a few seconds. → <a href="/en/formulare/eintraege-bearbeiten">Editing entries via form</a></p><div class="warning custom-block"><p class="custom-block-title">A forgotten flow is the most common mistake</p><p>If the app keeps syncing after clocking in, the flow is not active or writes to a different field. Check the row for a value in <code>editLink</code>.</p></div><h2 id="_5-the-tabs-row" tabindex="-1">5. The tabs row <a class="header-anchor" href="#_5-the-tabs-row" aria-label="Permalink to &quot;5. The tabs row&quot;">​</a></h2><p>In the team Space, add a row to the <code>tabs</code> Grid:</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Value</th></tr></thead><tbody><tr><td><code>title</code></td><td>for example &quot;Times&quot;</td></tr><tr><td><code>icon</code></td><td>single-colour SVG</td></tr><tr><td><code>type</code></td><td><code>TimeTracking</code></td></tr><tr><td><code>uri</code></td><td>the link of the shared view</td></tr><tr><td><code>formUri</code></td><td>the link of the form</td></tr></tbody></table><p><code>formUri</code> is a new Weblink field in the tabs Grid. Add it if it is missing, and add <code>TimeTracking</code> to the Single Select of <code>type</code>. → <a href="/en/apptiveteams/tabs">Setting up tabs</a></p><div class="tip custom-block"><p class="custom-block-title">Times inside the team Space</p><p>If the times live in the team Space itself and members may see the Grid, point <code>gridUri</code> at the Grid or view instead of <code>uri</code>. <code>formUri</code> is still needed. If both are set, <code>gridUri</code> wins.</p></div><h2 id="how-the-app-works" tabindex="-1">How the app works <a class="header-anchor" href="#how-the-app-works" aria-label="Permalink to &quot;How the app works&quot;">​</a></h2><ul><li><strong>Clock in</strong> immediately creates a row without an end. The timer keeps running on all of the person&#39;s devices, even after restarting the app.</li><li><strong>Break</strong> stores its start in <code>breakStart</code>; <strong>End break</strong> adds the minutes to <code>breakMinutes</code>. Breaks are rounded to whole minutes.</li><li><strong>Clock out</strong> sets the end. Net time is end minus start minus breaks.</li><li><strong>Manual entries</strong> via the plus button may be on any date. Editing is only possible for today&#39;s entries; there is no deleting in the app, corrections happen in the Grid.</li><li>After six hours without a break a hint reminds of the break.</li><li>The app shows its texts in the device language (German or English) and uses the team Space&#39;s primary colour.</li></ul><h2 id="if-something-is-missing" tabindex="-1">If something is missing <a class="header-anchor" href="#if-something-is-missing" aria-label="Permalink to &quot;If something is missing&quot;">​</a></h2><p>The app names missing field keys right in the tab, together with the fields the view or form actually delivers. If <code>breakStart</code> is missing in the form, for example, this shows up as a message after the first clock in.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td>No tab in the app</td><td>Tabs row incomplete: <code>type</code>, <code>uri</code> or <code>formUri</code> missing, or the icon is not an SVG</td></tr><tr><td>&quot;Missing field keys: …&quot; when opening</td><td>Field missing in the view or without a key</td></tr><tr><td>&quot;Saving failed&quot; with missing keys after clocking in</td><td>Field missing in the form</td></tr><tr><td>Permanently &quot;Syncing with ApptiveGrid …&quot;</td><td>Flow not active or <code>editLink</code> not visible in the view</td></tr><tr><td>Someone sees other people&#39;s times</td><td>View not filtered on &quot;Created by is the signed-in user&quot;</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/tabs">Setting up tabs</a></li><li><a href="/en/formulare/eintraege-bearbeiten">Editing entries via form</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>`,34)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
